public class DeferredSupport {public static int trace,mode,field,marks;public static final RuntimeException FAIL=new IllegalStateException("chosen");public static int value(){trace=trace*10+1;if(mode==1)throw FAIL;return field;}public static int take(int value){trace=trace*10+3;if(mode==3)throw FAIL;return value+1;}public static void mark(){trace=trace*10+2;marks++;field=9;if(mode==2&&marks==1||mode==4&&marks==2)throw FAIL;}}
